-- composition of rule kernels grouping_sets x statistics_propagation (duckdb), template union
SELECT count(*) FROM (SELECT 1 AS k FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, BOOL_AND (FALSE) AS c1, [NULL]::text[] AS c2 FROM rc AS a1 GROUP BY ROLLUP (a1.c0) UNION (SELECT FALSE AS c0, TRUE AS c1, []::text[] AS c2 UNION SELECT TRUE AS c0, TRUE AS c1, []::text[] AS c2)) AS ka UNION ALL SELECT 2 AS k FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT 100 AS c0, 16 AS c1 UNION SELECT 27 AS c0, 17 AS c1) AS kb) AS u;
